// Schema drift (designer doc 17 § 7): the JSON is generated by `workbench/tools/gen_wb_schema.py`
// and never edited by hand. The generator runs on a copy; its output must equal the committed
// files, and the package's copy must equal the design package's (a designer update shows here).

import { execFileSync } from 'node:child_process';
import { cpSync, mkdtempSync, readdirSync, readFileSync, rmSync, statSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join, relative } from 'node:path';
import { fileURLToPath } from 'node:url';
import { afterAll, describe, expect, it } from 'vitest';

import { CONTRACT_DIR } from '../src/index.js';

const DESIGN_DIR = fileURLToPath(
  new URL('../../../docs/design/salvage-yard/workbench/', import.meta.url),
);

const listFiles = (root: string, dir = root): string[] =>
  readdirSync(dir).flatMap((name) => {
    const full = join(dir, name);
    return statSync(full).isDirectory() ? listFiles(root, full) : [relative(root, full)];
  });

const generated = (root: string) =>
  listFiles(root)
    .filter((f) => f.startsWith('schema/') || f.startsWith('examples/'))
    .sort();

describe('workbench contract drift', () => {
  const work = mkdtempSync(join(tmpdir(), 'wb-contract-'));
  afterAll(() => rmSync(work, { recursive: true, force: true }));

  it('the generator reproduces the committed JSON', () => {
    cpSync(join(CONTRACT_DIR, 'tools'), join(work, 'tools'), { recursive: true });
    execFileSync('python3', [join(work, 'tools', 'gen_wb_schema.py')], { stdio: 'pipe' });
    expect(generated(work)).toEqual(generated(CONTRACT_DIR));
    for (const file of generated(CONTRACT_DIR))
      expect(readFileSync(join(work, file), 'utf8'), file).toBe(
        readFileSync(join(CONTRACT_DIR, file), 'utf8'),
      );
  });

  it("the package's copy equals the design package's", () => {
    const ours = listFiles(CONTRACT_DIR).sort();
    expect(ours).toEqual(listFiles(DESIGN_DIR).sort());
    for (const file of ours)
      expect(readFileSync(join(CONTRACT_DIR, file), 'utf8'), file).toBe(
        readFileSync(join(DESIGN_DIR, file), 'utf8'),
      );
  });
});
